#!/usr/bin/env node
import { createInterface } from "node:readline";

import { createFixtureSnapshots } from "./mcp-app-fixture-contract.mjs";

const { portable, claudeMcp, chatGpt } = createFixtureSnapshots();

function createResourceListItem(resource = portable.resource) {
  return {
    uri: resource.uri,
    name: resource.name,
    mimeType: resource.mimeType,
    description: "Orders fixture dashboard HTML resource.",
    _meta: resource._meta,
  };
}

function createToolListItem(tool) {
  return {
    name: tool.name,
    title: tool.title,
    description: tool.description,
    inputSchema: {
      type: "object",
      additionalProperties: false,
      properties: {},
    },
    _meta: {
      ...tool._meta,
      visibility: tool.visibility,
    },
  };
}

function resultFor(method, params = {}) {
  switch (method) {
    case "initialize":
      return {
        protocolVersion: "2025-06-18",
        capabilities: {
          resources: {},
          tools: {},
        },
        serverInfo: {
          name: "mcp-app-ui-orders-fixture",
          version: portable.version,
        },
      };
    case "resources/list":
      return {
        resources: [createResourceListItem()],
      };
    case "resources/read":
      if (params.uri !== portable.resource.uri) {
        throw new Error(`Unknown resource URI: ${params.uri}`);
      }

      return {
        contents: [
          {
            uri: portable.resource.uri,
            mimeType: portable.resource.mimeType,
            text: portable.resource.text,
            _meta: portable.resource._meta,
          },
        ],
      };
    case "tools/list":
      return {
        tools: portable.tools.map(createToolListItem),
      };
    case "tools/call": {
      const tool = portable.tools.find((candidate) => candidate.name === params.name);

      if (!tool) {
        throw new Error(`Unknown tool: ${params.name}`);
      }

      return {
        content: [
          {
            type: "text",
            text: JSON.stringify(tool.structuredContent),
          },
        ],
        structuredContent: tool.structuredContent,
        _meta: {
          ...tool._meta,
          visibility: tool.visibility,
        },
      };
    }
    case "fixture/export":
      return {
        portable,
        claudeMcp,
        chatGpt,
      };
    case "shutdown":
      queueMicrotask(() => process.exit(0));
      return null;
    default:
      throw new Error(`Unsupported method: ${method}`);
  }
}

function writeMessage(message) {
  process.stdout.write(`${JSON.stringify(message)}\n`);
}

function writeError(id, error) {
  writeMessage({
    jsonrpc: "2.0",
    id,
    error: {
      code: -32603,
      message: error.message,
    },
  });
}

const lines = createInterface({
  input: process.stdin,
  crlfDelay: Number.POSITIVE_INFINITY,
});

lines.on("line", (line) => {
  if (line.trim() === "") {
    return;
  }

  let request;

  try {
    request = JSON.parse(line);
  } catch (error) {
    writeError(null, error);
    return;
  }

  if (request.id === undefined) {
    return;
  }

  try {
    writeMessage({
      jsonrpc: "2.0",
      id: request.id,
      result: resultFor(request.method, request.params),
    });
  } catch (error) {
    writeError(request.id, error);
  }
});

