import { createChatGptAppSnapshot } from "@mcp-app-ui/chatgpt-app";
import { createClaudeMcpAppSnapshot } from "@mcp-app-ui/claude-mcp";

export const sharedContract = defineMcpAppContract({
  name: "orders-fixture",
  version: "0.1.0",
  resource: {
    uri: "ui://orders-fixture/dashboard.html",
    name: "orders-dashboard",
    mimeType: "text/html;profile=mcp-app",
    html: "<!doctype html><html><head><meta charset=\"utf-8\"><title>Orders</title></head><body><main><h1>Orders</h1><div id=\"orders-root\"></div></main></body></html>",
  },
  displayModes: ["inline", "fullscreen"],
  tools: [
    {
      name: "orders.list",
      title: "List orders",
      description: "Returns recent orders for the fixture dashboard.",
      resourceUri: "ui://orders-fixture/dashboard.html",
      access: {
        modelVisible: true,
        appVisible: true,
      },
      structuredResult: {
        orders: [
          {
            id: "order-1001",
            status: "ready",
          },
        ],
      },
    },
    {
      name: "orders.refresh",
      title: "Refresh orders",
      description: "Refreshes order data from the app surface only.",
