import {
  createAppSurface,
  type AppSurfaceDefinition,
  createPortableMcpAppSnapshot,
  type McpAppContract,
  type PortableMcpAppSnapshot,
  type StarterAppView,
} from "@mcp-app-ui/core";

export type ChatGptAppSurfaceDefinition = Omit<AppSurfaceDefinition, "host">;

export function createChatGptAppSurface(
  definition: ChatGptAppSurfaceDefinition,
): AppSurfaceDefinition {
  return createAppSurface(definition);
}

export interface ChatGptAppDescriptor {
  host: "chatgpt";
  metadata: StarterAppView["metadata"];
  surface: StarterAppView["view"];
  actions: StarterAppView["actions"];
}

export function createChatGptAppDescriptor(
  view: StarterAppView,
): ChatGptAppDescriptor {
  return {
    host: "chatgpt",
    metadata: view.metadata,
    surface: view.view,
    actions: view.actions,
  };
}

export interface ChatGptAppSnapshot {
  host: "chatgpt";
  portable: PortableMcpAppSnapshot;
  resource: PortableMcpAppSnapshot["resource"] & {
    _meta: PortableMcpAppSnapshot["resource"]["_meta"] & {
      "openai/widgetCSP": PortableMcpAppSnapshot["resource"]["_meta"]["ui"]["csp"];
      "openai/widgetDisplayModes": McpAppContract["displayModes"];
    };
  };
  tools: Array<
    PortableMcpAppSnapshot["tools"][number] & {
      _meta: PortableMcpAppSnapshot["tools"][number]["_meta"] & {
        "openai/outputTemplate": McpAppContract["resource"]["uri"];
        "openai/widgetAccessible": boolean;
      };
    }
  >;
}

export function createChatGptAppSnapshot(
  contract: McpAppContract,
): ChatGptAppSnapshot {
  const portable = createPortableMcpAppSnapshot(contract);

  return {
    host: "chatgpt",
    portable,
    resource: {
      ...portable.resource,
      _meta: {
        ...portable.resource._meta,
        "openai/widgetCSP": portable.resource._meta.ui.csp,
        "openai/widgetDisplayModes": contract.displayModes,
      },
    },
    tools: portable.tools.map((tool) => ({
      ...tool,
      _meta: {
        ...tool._meta,
        "openai/outputTemplate": tool._meta.ui.resourceUri,
        "openai/widgetAccessible": tool.visibility.appVisible,
      },
    })),
  };
}

export type ChatGptOpenAiCapability =
  | "requestDisplayMode"
  | "requestClose"
  | "openExternal";

export interface ChatGptOpenAiHost {
  openai?: Partial<Record<ChatGptOpenAiCapability, unknown>>;
}

export interface ChatGptOpenAiCapabilitySnapshot {
  host: "chatgpt";
  surface: "window.openai";
  available: boolean;
  capabilities: Partial<Record<ChatGptOpenAiCapability, boolean>>;
  missingCapabilities: ChatGptOpenAiCapability[];
  posture: "host-capable" | "fallback";
  reason?: "host_missing" | "capability_missing";
}

export interface ChatGptOpenAiInvocationResult {
  host: "chatgpt";
  surface: "window.openai";
  capability: ChatGptOpenAiCapability;
  posture: "host-called" | "fallback";
  result?: unknown;
  reason?: "host_missing" | "capability_missing" | "host_helper_failed";
  errorMessage?: string;
}

export function inspectChatGptOpenAiCapabilities(
  host: ChatGptOpenAiHost,
  expectedCapabilities: ChatGptOpenAiCapability[] = ["requestDisplayMode"],
): ChatGptOpenAiCapabilitySnapshot {
  const capabilities = Object.fromEntries(
    expectedCapabilities.map((capability) => [
      capability,
      typeof host.openai?.[capability] === "function",
    ]),
  ) as Partial<Record<ChatGptOpenAiCapability, boolean>>;
  const missingCapabilities = expectedCapabilities.filter(
    (capability) => !capabilities[capability],
  );

  if (!host.openai) {
    return {
      host: "chatgpt",
      surface: "window.openai",
      available: false,
      capabilities,
      missingCapabilities,
      posture: "fallback",
      reason: "host_missing",
    };
  }

  if (missingCapabilities.length > 0) {
    return {
      host: "chatgpt",
      surface: "window.openai",
      available: true,
      capabilities,
      missingCapabilities,
      posture: "fallback",
      reason: "capability_missing",
    };
  }

  return {
    host: "chatgpt",
    surface: "window.openai",
    available: true,
    capabilities,
    missingCapabilities,
    posture: "host-capable",
  };
}

export async function invokeChatGptOpenAiCapability(
  host: ChatGptOpenAiHost,
  capability: ChatGptOpenAiCapability,
  ...args: unknown[]
): Promise<ChatGptOpenAiInvocationResult> {
  if (!host.openai) {
    return {
      host: "chatgpt",
      surface: "window.openai",
      capability,
      posture: "fallback",
      reason: "host_missing",
    };
  }

  const helper = host.openai[capability];
  if (typeof helper !== "function") {
    return {
      host: "chatgpt",
      surface: "window.openai",
      capability,
      posture: "fallback",
      reason: "capability_missing",
    };
  }

  try {
    return {
      host: "chatgpt",
      surface: "window.openai",
      capability,
      posture: "host-called",
      result: await helper(...args),
    };
  } catch (error) {
    return {
      host: "chatgpt",
      surface: "window.openai",
      capability,
      posture: "fallback",
      reason: "host_helper_failed",
      errorMessage: error instanceof Error ? error.message : String(error),
    };
  }
}

