type JsonMap = Record<string, unknown>;

function isRecord(value: unknown): value is JsonMap {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function formatValue(value: unknown): string {
  return JSON.stringify(value, null, 2);
}

function assert(condition: boolean, message: string): asserts condition {
  if (!condition) {
    throw new Error(message);
  }
}

function assertRecord(value: unknown, path: string): JsonMap {
  assert(isRecord(value), `${path} must be an object`);
  return value;
}

function assertArray(value: unknown, path: string): unknown[] {
  assert(Array.isArray(value), `${path} must be an array`);
  return value;
}

function assertEqual(actual: unknown, expected: unknown, message: string): void {
  assert(
    actual === expected,
    `${message}: expected ${formatValue(expected)}, got ${formatValue(actual)}`,
  );
}

function assertDeepEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson = JSON.stringify(actual);
  const expectedJson = JSON.stringify(expected);
  assert(
    actualJson === expectedJson,
    `${message}: expected ${formatValue(expected)}, got ${formatValue(actual)}`,
  );
}

function getRecord(value: unknown, path: string): JsonMap {
  return assertRecord(value, path);
}

function getArray(value: unknown, path: string): unknown[] {
  return assertArray(value, path);
}

function getMeta(value: JsonMap, path: string): JsonMap {
  return getRecord(value._meta, `${path}._meta`);
}

function getUiMeta(value: JsonMap, path: string): JsonMap {
  return getRecord(getMeta(value, path).ui, `${path}._meta.ui`);
}

function getVisibility(value: JsonMap, path: string): JsonMap {
  return getRecord(value.visibility, `${path}.visibility`);
}

function getServerVisibility(value: JsonMap, path: string): JsonMap {
  return getRecord(getMeta(value, path).visibility, `${path}._meta.visibility`);
}

function getTools(snapshot: JsonMap, path: string): JsonMap[] {
  return getArray(snapshot.tools, `${path}.tools`).map((tool, index) =>
