  if (request.method === "GET" && url.pathname === "/fixture/metadata") {
    jsonResponse(response, 200, {
      resourceUri: portable.resource.uri,
      mimeType: portable.resource.mimeType,
      tools: portable.tools.map((tool) => ({
        name: tool.name,
        visibility: tool.visibility,
        resourceUri: tool._meta.ui.resourceUri,
      })),
      chatGptAdapterSnapshotAvailable: true,
      bridge: {
        endpoint: "/mcp",
        transport: "validation-only-http-json-rpc",
      },
    });
