  if (request.method !== "POST" || url.pathname !== "/mcp") {
    jsonResponse(response, 404, {
      error: "not_found",
      endpoints: ["/healthz", "/fixture/metadata", "/mcp"],
    });
    return;
  }

  try {
    const body = await readBody(request);
    const payload = JSON.parse(body);
    const messages = Array.isArray(payload) ? payload : [payload];
    const replies = messages.map(handleRpcMessage).filter(Boolean);

    if (replies.length === 0) {
      emptyResponse(response, 202);
      return;
    }

    jsonResponse(response, 200, Array.isArray(payload) ? replies : replies[0]);
  } catch (error) {
    jsonResponse(response, 400, {
      jsonrpc: "2.0",
      id: null,
      error: {
        code: -32700,
        message: error instanceof Error ? error.message : String(error),
      },
    });
  }
});

server.listen(port, host, () => {
  const address = server.address();
  const actualPort = typeof address === "object" && address ? address.port : port;
  process.stderr.write(
    `mcp-app-ui orders fixture HTTP bridge listening on http://${host}:${actualPort}/mcp\n`,
  );
});
